package io.github.eleasarb.glagolik.data.db

import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase

/**
 * Read-only verb content, shipped as `assets/verbs.db` (generated by tools/importer).
 *
 * The version must equal PRAGMA user_version of the asset, i.e. `version` in
 * data/content-version.txt. The importer bumps it on every content change; Room then
 * replaces the installed copy (destructive fallback + createFromAsset). Learning progress
 * lives in ProgressDatabase, so replacing this one never touches user data.
 */
@Database(
    entities = [VerbEntity::class, VerbFormEntity::class, AspectPartnerEntity::class],
    version = VerbsDatabase.VERSION,
    exportSchema = true,
)
abstract class VerbsDatabase : RoomDatabase() {
    abstract fun verbDao(): VerbDao

    companion object {
        const val VERSION = 1
        private const val ASSET = "verbs.db"
        private const val NAME = "verbs.db"

        fun create(context: Context): VerbsDatabase =
            Room.databaseBuilder(context, VerbsDatabase::class.java, NAME)
                .createFromAsset(ASSET)
                .fallbackToDestructiveMigration(dropAllTables = true)
                .build()
    }
}
